<template><div class="login-page"><el-card class="login-card"><h1>图书管理系统</h1><p class="muted">Library Management</p><el-form :model="form" @submit.prevent="login"><el-form-item><el-input v-model="form.username" placeholder="账号" /></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="密码" /></el-form-item><el-form-item><el-radio-group v-model="form.role"><el-radio-button label="ADMIN">管理员</el-radio-button><el-radio-button label="READER">读者</el-radio-button></el-radio-group></el-form-item><el-button type="primary" native-type="submit" class="full">登录</el-button></el-form></el-card></div></template>
<script setup>import { reactive } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import http from '../api/http';const router=useRouter();const form=reactive({username:'admin',password:'',role:'ADMIN'});async function login(){try{const r=await http.post('/auth/login',form);if(r.code!==200)throw Error(r.message);localStorage.setItem('library_token',r.data.token);localStorage.setItem('library_user',JSON.stringify(r.data.user));router.push('/')}catch(e){ElMessage.error(e.message||'登录失败')}};</script>
<style scoped>.login-page{height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#eff6ff,#dbeafe)}.login-card{width:380px;padding:18px}.login-card h1{text-align:center;margin:8px 0}.muted{text-align:center;color:#94a3b8}.full{width:100%}</style>
